					or not is_finite(float(hp)) or not is_finite(float(maximum)) or float(maximum) <= 0.0 \
					or float(hp) < 0.0 or float(hp) > float(maximum) or not row.get("fainted") is bool \
					or row.fainted != (float(hp) == 0.0):
