patch=[]
for f in sorted((ROOT/'after').rglob('*')):
 if not f.is_file():continue
 p=f.relative_to(ROOT/'after').as_posix(); before=ROOT/'before'/p
 old=before.read_bytes() if before.exists() else b'';new=f.read_bytes()
 if old==new:continue
 patch.append(''.join(difflib.unified_diff(old.decode('utf-8').splitlines(True),new.decode('utf-8').splitlines(True),fromfile='a/'+p if before.exists() else '/dev/null',tofile='b/'+p)))
 manifest['files'].append({'path':p,'before_sha256':hashlib.sha256(old).hexdigest() if before.exists() else None,'after_sha256':hashlib.sha256(new).hexdigest(),'added_lines':len(new.splitlines())-len(old.splitlines())})
(ROOT/'proposal.patch').write_text(''.join(patch),encoding='utf-8',newline='')
